import{_ as t,o as a,c as o,aA as i}from"./chunks/framework.Dl8a02nG.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"demos/overviews/eeglab_import.md","filePath":"demos/overviews/eeglab_import.md","lastUpdated":null}'),r={name:"demos/overviews/eeglab_import.md"};function s(n,e,l,p,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<p>This demo demonstrates importing EEGLAB <code>.set</code> files into EegFun.jl. EEGLAB is a widely used open-source toolboxes for EEG processing (in MATLAB).</p><h3 id="About-EEGLAB-.set-Format" tabindex="-1">About EEGLAB .set Format <a class="header-anchor" href="#About-EEGLAB-.set-Format" aria-label="Permalink to &quot;About EEGLAB .set Format {#About-EEGLAB-.set-Format}&quot;">​</a></h3><p>The <code>.set</code> format is a MATLAB-based file that contains a header structure with all recording parameters, trigger information, and often precomputed info like ICA weights or epoch definitions. The actual EEG data may be stored within the <code>.set</code> file or in a separate <code>.fdt</code> file.</p><p><strong>Key features</strong>:</p><ul><li><p>Supports both continuous and epoched data</p></li><li><p>Often includes ICA components and weights</p></li><li><p>Comprehensive metadata storage</p></li></ul><h3 id="Import-Capabilities" tabindex="-1">Import Capabilities <a class="header-anchor" href="#Import-Capabilities" aria-label="Permalink to &quot;Import Capabilities {#Import-Capabilities}&quot;">​</a></h3><p><strong>Data loading</strong>:</p><ul><li><p>Automatic detection of continuous vs. epoched data</p></li><li><p>Import of ICA weights and sphere matrices, if available</p></li><li><p>Mapping of event/trigger labels (hashed to triggers)</p></li><li><p>Support for external data files (.fdt)</p></li></ul><h3 id="Data-Mapping" tabindex="-1">Data Mapping <a class="header-anchor" href="#Data-Mapping" aria-label="Permalink to &quot;Data Mapping {#Data-Mapping}&quot;">​</a></h3><p><strong>EegFun.read_eeglab</strong> handles the mapping EEGLAB structures to native EegFun types:</p><ul><li><p>EEGLAB Dataset → <code>ContinuousData</code> or <code>EpochedData</code></p></li><li><p>ICA info → <code>ICA</code> structure</p></li><li><p>Event labels → Available in <code>:trigger_info</code> column</p></li></ul><h2 id="Workflow-Summary" tabindex="-1">Workflow Summary <a class="header-anchor" href="#Workflow-Summary" aria-label="Permalink to &quot;Workflow Summary {#Workflow-Summary}&quot;">​</a></h2><ol><li><p><strong>Load Data</strong>: Depending on the file content, <code>read_eeglab()</code> can return just data or data plus ICA information.</p></li><li><p><strong>Check Triggers</strong>: EEGLAB often uses string labels for events. EegFun hashes these for its trigger system while preserving the original labels.</p></li><li><p><strong>Verification</strong>: Use <code>plot_databrowser()</code> to verify the imported time series or epochs.</p></li><li><p><strong>ICA Visualization</strong>: If ICA information was imported, you can immediately plot components and activations.</p></li></ol>',13)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
